/**
 * The only Markdown grammar accepted for assistant messages.
 *
 * This intentionally renders a small, safe subset instead of accepting HTML.
 * Raw markup is escaped, links are limited to http(s), and every attribute is
 * generated by this module so callers never have to trust model output.
 */
export function safeLinkUrl(value: string): string | null {
  try {
    const url = new URL(value.trim());
    return url.protocol === "http:" || url.protocol === "https:" ? url.toString() : null;
  } catch {
    return null;
  }
}

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function renderInline(value: string): string {
  const pattern = /(\[([^\]]+)\]\(([^\s)]+)(?:\s+["']([^"']*)["'])?\)|`([^`]+)`|\*\*([^*]+)\*\*|__([^_]+)__|(?<!\w)\*([^*]+)\*(?!\w)|(?<!\w)_([^_]+)_(?!\w))/g;
  let output = "";
  let cursor = 0;
  for (const match of value.matchAll(pattern)) {
    const index = match.index ?? 0;
    output += escapeHtml(value.slice(cursor, index));
    if (match[2] !== undefined) {
      const href = safeLinkUrl(match[3]);
      output += href
        ? `<a href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer">${escapeHtml(match[2])}</a>`
        : escapeHtml(match[2]);
    } else if (match[5] !== undefined) {
      output += `<code>${escapeHtml(match[5])}</code>`;
    } else if (match[6] !== undefined || match[7] !== undefined) {
      output += `<strong>${escapeHtml(match[6] ?? match[7] ?? "")}</strong>`;
    } else {
      output += `<em>${escapeHtml(match[8] ?? match[9] ?? "")}</em>`;
    }
    cursor = index + match[0].length;
  }
  return output + escapeHtml(value.slice(cursor));
}

export function markdownToSafeHtml(markdown: string): string {
  const lines = String(markdown ?? "").replaceAll("\r\n", "\n").replaceAll("\r", "\n").split("\n");
  const blocks: string[] = [];
  let paragraph: string[] = [];
  let listType: "ol" | "ul" | null = null;
  let listItems: string[] = [];

  const flushList = () => {
    if (!listType || !listItems.length) return;
    blocks.push(`<${listType}>${listItems.map((item) => `<li>${renderInline(item)}</li>`).join("")}</${listType}>`);
    listType = null;
    listItems = [];
  };
  const flushParagraph = () => {
    if (!paragraph.length) return;
    blocks.push(`<p>${paragraph.map((line) => renderInline(line)).join(" ")}</p>`);
    paragraph = [];
  };

  for (const line of lines) {
    const ordered = line.match(/^\s*\d+[.)]\s+(.+)$/);
    const unordered = line.match(/^\s*[-*+]\s+(.+)$/);
    if (ordered || unordered) {
      flushParagraph();
      const nextType = ordered ? "ol" : "ul";
      if (listType && listType !== nextType) flushList();
      listType = nextType;
      listItems.push((ordered ?? unordered)?.[1] ?? "");
      continue;
    }
    flushList();
    if (!line.trim()) {
      flushParagraph();
      continue;
    }
    paragraph.push(line.trim());
  }
  flushList();
  flushParagraph();
  return blocks.join("");
}

export function renderMarkdownInto(documentRef: Document, container: HTMLElement, markdown: string): void {
  // markdownToSafeHtml only emits escaped text plus the allow-listed elements
  // above. Clearing first also prevents stale content from surviving updates.
  container.replaceChildren();
  container.innerHTML = markdownToSafeHtml(markdown);
}
